#include <bits/stdc++.h>
using namespace std;
#define int long long

const int N = 1e5 + 5, LOG = 20, INF = 1e18;

int n, m;
int a[N * 2], st[LOG][N], cnt[N];

int jump(int x){
	int now = 0, sec = 0;
	for(int i = LOG - 1; i >= 0; -- i)
		if(now + st[i][x] <= n){
			now += st[i][x];
			sec += (1 << i);
			x = (x + st[i][x] - 1) % n + 1;
		}
	return sec;
}

signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);

	cin >> n >> m;
	for(int i = 1; i <= n; ++ i)
		cin >> a[i], a[i + n] = a[i];

	int r = 0, tot = 0;
	for(int i = 1; i <= n; ++ i){
		while(tot < m && r < 2 * n)
			if(!(cnt[a[++ r]] ++))
				++ tot;
		st[0][i] = r - i + 1;
		if(!(-- cnt[a[i]]))
			-- tot;
	}

	for(int i = 1; i < LOG; ++ i)
		for(int j = 1; j <= n; ++ j){
			int to = (j + st[i - 1][j] - 1) % n + 1;
			st[i][j] = min(st[i - 1][j] + st[i - 1][to], INF);
		}

	int ans = 0;
	for(int i = 1; i <= n; ++ i)
		ans = max(ans, jump(i));

	cout << ans;

	return 0;
}
